        retroGuide("retro.start-here", "Retro and Android: start with the exact device", "A safe starting point for console homebrew, Android root and custom software. Compatibility depends on the exact model and software build, so identify those before choosing a guide.",
            block("Record first", "Device family and exact model or board revision:", "Current system software / Android version and full build number:", "Region and any previous modification:", "What you want to do: homebrew, preservation, repair, custom ROM, or another specific goal:", "Back up saves and personal files before any change."),
            block("Choose a source", "Use the project's own documentation or release page for downloads and compatibility.", "Check the listed model and firmware against your own device; a similar model number may not be compatible.", "Do not update system software until you have checked whether the change affects your intended project.", "Prefer reversible, documented steps. Stop if the guide does not match the device or a checksum/signature differs.", "Use legally obtained software and your own backups; a homebrew catalogue is not a source for commercial game downloads."),
            sources = consoleBasics + listOf("Android Developers — official platform documentation" to "https://developer.android.com/about/versions")),

        retroGuide("retro.android-version-map", "Android versions and API levels", "A version lookup from Android 1.0 through Android 17. As reviewed on 19 October 2026, Android 17 is still in public beta; its API level is 37. The OS version alone does not determine root or ROM compatibility.",
            block("Version and API reference", "Android 1.0 — API 1; Android 1.1 — API 2; Android 1.5 Cupcake — API 3; Android 1.6 Donut — API 4.", "Android 2.0 Eclair — API 5; 2.0.1 — API 6; 2.1 — API 7; Android 2.2 Froyo — API 8.", "Android 2.3 Gingerbread — API 9; 2.3.3 — API 10; Android 3.0 Honeycomb — API 11; 3.1 — API 12; 3.2 — API 13.", "Android 4.0 Ice Cream Sandwich — API 14; 4.0.3 — API 15; Android 4.1 Jelly Bean — API 16; 4.2 — API 17; 4.3 — API 18.", "Android 4.4 KitKat — API 19; 4.4W wearable — API 20; Android 5.0 Lollipop — API 21; 5.1 — API 22.", "Android 6 Marshmallow — API 23; Android 7.0 Nougat — API 24; 7.1 — API 25; Android 8.0 Oreo — API 26; 8.1 — API 27.", "Android 9 Pie — API 28; Android 10 — API 29; Android 11 — API 30; Android 12 — API 31; Android 12L — API 32.", "Android 13 — API 33; Android 14 — API 34; Android 15 — API 35; Android 16 — API 36. Android 17 — API 37; Android Developers' 17 release notes identify beta builds, so treat its APIs and behaviour as pre-release."),
            block("Check your own device", "Open Settings → About phone/tablet and record Android version, model, build number and security patch.", "Android Developers documents platform versions and API levels; AOSP documents build IDs.", "For modification compatibility, use the device maker and the specific project guide, not a generic Android-version exploit list.", "Android 17's API 37 and beta status were checked against the official Android Developers and AOSP pages on 19 October 2026."),
            sources = androidVersionSources + listOf("Android 17 official release notes" to "https://developer.android.com/about/versions/17/release-notes", "AOSP build numbers and API levels" to "https://source.android.com/docs/setup/reference/build-numbers")),

        retroGuide("retro.android-architecture", "Android architecture and app development", "A practical map of Android's system layers and the tools used to build and diagnose apps. Device builds can differ, so platform documentation and the device's own configuration matter.",
            block("System layers", "Android apps use framework APIs and communicate with system services through defined interfaces. The framework relies on Android Runtime (ART), native components, vendor interfaces and a Linux kernel.", "The Hardware Abstraction Layer (HAL) lets Android system components use vendor-specific hardware implementations through stable interfaces.", "Application sandboxing assigns each app a distinct Linux identity. Permissions add user-controlled access to protected capabilities; they do not replace the sandbox.", "Verified Boot checks the integrity chain from the bootloader onward. Partition layouts and update mechanisms vary across device generations."),
            block("Build and inspect an app", "Kotlin source is compiled into DEX bytecode and packaged in an APK; app bundles are publishing inputs from which stores can generate device-specific APKs.", "Android Studio and Gradle build the project. The manifest declares components and capabilities, while runtime permission requests should happen in context.", "Use ADB for authorized debugging, Logcat for diagnostic output, and Android Studio profilers to inspect performance. Never include tokens or private note contents in logs.", "Use a disposable test device or emulator for experiments. Keep production app data and signing keys out of sample projects."),
            block("A safe first investigation", "Read the app's manifest and dependency list, then inspect its declared minimum and target SDKs.", "Use Android Studio's APK Analyzer or apkanalyzer to inspect package contents and DEX metadata without modifying the installed app.", "For a runtime fault, capture the smallest useful Logcat window around the error and remove personal identifiers before sharing it.", "When a claim depends on a specific API or behaviour, check the official versioned Android documentation."),
            sources = listOf("AOSP platform architecture" to "https://source.android.com/docs/core/architecture", "Android app fundamentals" to "https://developer.android.com/guide/components/fundamentals", "Android Studio APK Analyzer" to "https://developer.android.com/studio/debug/apk-analyzer", "Android Debug Bridge" to "https://developer.android.com/tools/adb")),

        retroGuide("retro.android-tv", "Android TV and Google TV: local setup", "A setup checklist for Android TV and Google TV devices, with practical notes on apps, local media, networking and developer access.",
            block("Identify the device and display path", "Record the exact model, Android TV OS version, available storage and whether the display is connected directly or through an AVR/switch.", "Confirm the TV and device support the resolution, refresh rate, HDR format and audio formats you plan to use. A capable app cannot add missing hardware decoder or HDMI support.", "For reliable high-bitrate local media, prefer wired Ethernet where available; otherwise test Wi-Fi in the device's actual location."),
            block("Local media and network shares", "Kodi, Plex and Jellyfin are separate apps with different server and library requirements. Check each project's current device support and codec documentation.", "SMB shares require reachable network paths and valid credentials. Use a dedicated, least-privilege media account instead of exposing a full computer account.", "DLNA discovery depends on local network multicast and router isolation settings. A client and server on guest networks may not see each other.", "Direct play avoids transcoding when the client supports the source format; transcoding adds server load and can reduce quality."),
            block("ADB and APK installation", "Enable developer options only when needed, then use Android's documented debugging workflow and authorize only a computer you control.", "An APK must match the device ABI, Android version and signing/update identity. Sideload only packages from a source you trust and can verify.", "Disable debugging after use and revoke old debugging authorizations if a device or computer is no longer trusted."),
            block("Troubleshooting", "If playback stutters, compare a local file with a network file, check Wi-Fi signal or Ethernet, and inspect whether the server is transcoding.", "If audio is missing, check the app's passthrough setting, AVR input, HDMI path and codec support one variable at a time.", "If a device is absent from a cast or DLNA list, confirm both devices share the same non-guest LAN and that client isolation is off."),
            sources = listOf("Android TV documentation" to "https://developer.android.com/training/tv", "Kodi wiki" to "https://kodi.wiki/", "Plex support" to "https://support.plex.tv/", "Jellyfin documentation" to "https://jellyfin.org/docs/")),

        retroGuide("retro.shield-overview", "NVIDIA Shield TV: hardware and media", "A model-aware guide to the Shield TV family, its strengths as a media client and the limits imposed by the connected display, network and software.",
            block("Identify the model", "Check Settings → Device Preferences → About for the device name and software version; compare the physical model number with NVIDIA's current support documentation.", "Shield TV and Shield TV Pro differ in enclosure, ports and storage expansion. Confirm the exact generation before buying accessories or following a teardown.", "Treat feature support as a combination of Shield hardware, app version, source media and TV/AVR capability."),
            block("Display and sound", "Connect directly to the TV first to establish a baseline. Add an AVR or HDMI switch only after confirming the basic picture and audio path.", "Resolution, HDR, refresh rate, HDMI-CEC and surround output depend on every device in the chain and their settings.", "A Shield screen-capture or casting feature does not automatically transmit every protected video surface to another television; DRM, HDCP and app policies can limit capture."),
            block("Storage and playback", "Use a supported external USB drive for local media; adoptable storage changes how Android uses the drive and can make it unsuitable for moving between devices.", "For a home media library, compare direct-play compatibility, server transcoding and network bandwidth before changing quality settings.", "Keep a second copy of irreplaceable media and configuration before formatting storage or resetting the device."),
            block("Troubleshooting", "For intermittent network playback, compare wired Ethernet and Wi-Fi and check whether another device saturates the link.", "For remote-control or CEC problems, test the Shield remote directly, then re-enable HDMI-CEC options one at a time.", "Before a factory reset, record the model, software version and app setup needed to restore the device."),
            sources = listOf("NVIDIA Shield TV support" to "https://www.nvidia.com/en-us/shield/support/", "Android TV documentation" to "https://developer.android.com/training/tv", "Plex support" to "https://support.plex.tv/", "Jellyfin documentation" to "https://jellyfin.org/docs/")),

        retroGuide("retro.shield-mirroring", "NVIDIA Shield: mirroring and second-TV limits", "There is no universal way to duplicate every Shield screen and protected video to another television. Choose a method based on whether you need the whole interface, a media stream or interactive play.",
            block("Choose the content path", "For a film or show, install the playback app on the second TV or its streaming device and access the same service or media server. This usually avoids capturing and re-encoding the Shield screen.", "For the full Shield interface, use a hardware HDMI distribution system with a second display output. It duplicates the HDMI signal but requires a source-to-destination cable path and compatible HDCP handling.", "For supported app content, casting or a media-server client can send the media selection to another receiver, but this does not mirror the whole launcher or every app."),
            block("Interactive streaming", "Game streaming adds video encoding on the Shield or host, network transport, decoding on the receiver and a separate return path for controller input.", "A receiver can display an HDMI mirror without sending controller input back to the Shield. Use a paired controller at the receiver only if the chosen streaming app forwards input.", "Wi-Fi, encoding load, receiver decode delay and network congestion all add latency. Test the actual path before relying on it for fast games."),
            block("Limits and checks", "Protected playback may use secure video paths that screen capture cannot read. App policies and DRM can show a black or blank image even when the interface is visible.", "An HDMI splitter or matrix cannot bypass HDCP restrictions; use compatible equipment and services.", "Start with a direct HDMI connection and one receiver, then add equipment gradually. Confirm picture, sound, CEC and remote-control behaviour separately."),
            sources = listOf("NVIDIA Shield TV support" to "https://www.nvidia.com/en-us/shield/support/", "Android media projection overview" to "https://developer.android.com/media/grow/media-projection", "Android TV documentation" to "https://developer.android.com/training/tv")),

        retroGuide("retro.whole-home-streaming", "Whole-home streaming and local network gaming", "A practical way to compare media clients, HDMI distribution and interactive game streaming without treating them as the same technology.",
            block("Three different approaches", "A native app on each TV plays its own stream and is usually the simplest route for subscription services or a home media server.", "HDMI distribution duplicates one source's audio/video signal over a physical cable or compatible matrix. It does not independently control the source from every room.", "Game streaming encodes a live screen, sends it across the network, decodes it at the receiver and forwards controller input back to the host."),
            block("Plan the network", "Prefer wired Ethernet for the host and receiver when possible. If using Wi-Fi, use a strong access point connection on a clear band and avoid guest/client-isolated networks.", "Available bandwidth is not the same as stable latency. Congestion, packet loss, retransmissions and buffer settings can cause stutter or input delay.", "Keep media servers and clients on a trusted home LAN. Do not expose SMB or remote-control ports directly to the public internet."),
            block("Measure and troubleshoot", "Test the receiver beside the router, then in its intended room; record resolution, frame rate, bitrate and whether the server transcodes.", "If video is smooth but controls feel delayed, test a wired controller at the receiver, reduce encoding load and compare the round-trip network path.", "For ordinary video, allow buffering for smooth playback. For interactive games, reduce buffering only if the connection remains stable."),
            sources = listOf("Moonlight game streaming" to "https://moonlight-stream.org/", "Sunshine host project" to "https://github.com/LizardByte/Sunshine", "Jellyfin documentation" to "https://jellyfin.org/docs/", "Kodi wiki" to "https://kodi.wiki/")),

        retroGuide("retro.emulation", "Emulation: files, controls and legal use", "A device-neutral checklist for setting up an emulator while keeping game files, firmware and save data within the rights that apply to you.",
            block("Know what each file is", "An emulator implements a system's hardware or software environment; a frontend organises emulator apps and libraries but is not itself a game collection.", "ROM, ISO, CHD and other extensions describe common image or container formats, not a licence or proof that the contents are lawful to download.", "Some systems require firmware or BIOS files. Use only files you are legally entitled to use and follow the emulator project's instructions."),
            block("Build a dependable setup", "Choose an actively maintained emulator with documentation for your exact Android version and device chipset.", "Keep original files untouched and use a separate working copy when converting images. Record checksums if the project supplies known-good values.", "Map one controller at a time, verify buttons in the emulator input screen, and save a per-system profile if controls differ.", "Store saves and states in a backed-up folder. Save states are not always portable across emulator versions or game revisions."),
            block("Improve performance carefully", "Start with native resolution and default timing. Change one graphics or audio option at a time so regressions are easy to identify.", "Higher internal resolution increases GPU work and heat. Reduce enhancements before assuming the device or game image is faulty.", "Use the emulator's compatibility database and issue tracker for game-specific workarounds; a title working on one chipset does not guarantee another will behave the same."),
            sources = listOf("RetroArch documentation" to "https://docs.libretro.com/", "DuckStation project" to "https://github.com/stenzek/duckstation", "Dolphin Emulator documentation" to "https://dolphin-emu.org/docs/", "F-Droid catalogue" to "https://f-droid.org/")),

        retroGuide("retro.console-care", "PlayStation hardware identification and care", "A careful inspection workflow for identifying a console before maintenance, repair or compatibility research.",
            block("Record the hardware", "Photograph the model label and record the complete SCPH, SCPH-xxxxx, CECH, CUH or CFI code before opening a device.", "Note the power rating, region, installed storage, visible ports and any prior modification. Similar retail names can hide substantial board and drive differences.", "Search the exact model code in original manufacturer documentation or a specialist hardware reference; do not infer compatibility from appearance alone."),
            block("Before maintenance", "Disconnect power and accessories, allow the console to cool and work on a clean, well-lit surface with a container for screws.", "Use the correct screwdriver and follow a model-specific disassembly guide. If a step requires force or the guide's board layout differs, stop and re-check the model.", "Keep liquids away from electronics. Avoid opening power-supply components; capacitors can retain dangerous charge after unplugging.", "Back up saves and important data before storage work, firmware changes or repairs that could erase or corrupt them."),
            block("Common symptoms", "For overheating or fan noise, check ventilation and external dust first; do not block vents or run the console inside a closed cabinet.", "For disc read faults, inspect the disc and try another known-good disc before assuming the optical pickup has failed.", "For display problems, test a known-good cable and display input, then check supported output modes. Change one part of the signal chain at a time.", "Use a qualified repairer for power, board-level or soldering work if you do not have the tools and experience."),
            sources = listOf("PlayStation support" to "https://www.playstation.com/support/", "PSX-Place hardware and repair community" to "https://www.psx-place.com/", "iFixit PlayStation repair guides" to "https://www.ifixit.com/Device/PlayStation")),

        retroGuide("retro.reverse-engineering", "Android application analysis: safe foundations", "A lawful, permission-based introduction to inspecting Android applications and their network behaviour. Use your own app or software you are authorised to assess.",
            block("Static inspection", "APK Analyzer can show package contents, manifest declarations, DEX files and resources. JADX can help read decompiled Java-like output, but decompilation is approximate and names may be obfuscated.", "DEX contains Android runtime bytecode; Smali is a human-readable assembly syntax for DEX. Decompiled output is evidence to investigate, not original source code.", "Check signing-certificate metadata, package identifiers and declared permissions. A signature identifies a signing key relationship; it does not prove an app is safe."),
            block("Dynamic inspection", "Use a test emulator or device with no personal accounts or data. Keep a clean snapshot so you can restore the baseline.", "Android Studio's debugger and Logcat can reveal execution state and errors. Avoid collecting credentials, private messages or data belonging to other users.", "For network observations, use a test app and a controlled lab network. Certificate pinning, TLS and platform protections may limit visibility; do not attempt to bypass another party's security without explicit authorisation."),
            block("Report findings", "Record the exact app version, device/API level, steps, expected behaviour and observed result.", "Redact tokens, account identifiers, IP addresses and personal content from captures before sharing.", "Use the developer's published security contact or responsible-disclosure process when you discover a vulnerability. Do not publish exploit details before coordinating where appropriate."),
            sources = listOf("Android Studio APK Analyzer" to "https://developer.android.com/studio/debug/apk-analyzer", "Android Debug Bridge" to "https://developer.android.com/tools/adb", "JADX decompiler" to "https://github.com/skylot/jadx", "OWASP MAS project" to "https://mas.owasp.org/")),

        retroGuide("retro.android-root-roms", "Android bootloader, root and custom ROMs", "A device-first roadmap for learning Android modification. Unlocking may erase data, affect warranty or disable security-sensitive features; the exact rules vary by manufacturer and model.",
            block("Before changing anything", "Record the exact model code, region/carrier, Android version, full build fingerprint and current bootloader state.", "Check whether the manufacturer permits bootloader unlocking for this exact model and region; some devices cannot be unlocked.", "Back up files and confirm you can restore the matching stock firmware before unlocking.", "Read the complete device-specific install guide. A custom ROM must explicitly list your device codename and required firmware base."),
            block("Trusted project starting points", "LineageOS publishes a device list and separate installation guide for each supported model; follow that exact page.", "Magisk's official repository and installation documentation explain supported root methods. Use an image from the exact installed build, not a random download.", "Android version numbers are not enough to select a boot, recovery or firmware image.", "Keep the original images and recovery route available. Do not interrupt a flash or relock a modified bootloader unless the device guide explicitly says to."),
            sources = listOf("Android Open Source Project — bootloader locking and unlocking" to "https://source.android.com/docs/core/architecture/bootloader/locking_unlocking", "LineageOS — device downloads and install guides" to "https://wiki.lineageos.org/devices/", "Magisk — official project and install documentation" to "https://github.com/topjohnwu/Magisk", "Android Developers — platform releases" to "https://developer.android.com/about/versions")),

        retroGuide("retro.ps1-homebrew", "PlayStation 1: homebrew and preservation", "PS1 projects include homebrew boot methods, development tools and optical-drive replacements. They are model- and hardware-specific; there is no single universal software jailbreak.",
            block("Project paths", "FreePSXBoot is a memory-card boot exploit project. Its upstream project warns that writing a supplied full-card image erases the memory card, so back up saves first.", "Unirom provides a homebrew boot and development environment for compatible cheat cartridges and boot methods; check its compatibility and usage pages.", "XStation is an optical-drive replacement requiring hardware installation; use the official board-specific installation guide and confirm the PU board revision.", "PSX.Dev is a community starting point for PlayStation homebrew development."),
            block("Before you begin", "Record the console model (SCPH number), board revision if known, region and the exact adapter/flash hardware.", "Back up memory-card saves before writing or formatting any card.", "Do not use a guide for a different board revision, and do not treat game images from unofficial download sites as homebrew."),
            sources = listOf("FreePSXBoot — upstream project and compatibility notes" to "https://github.com/brad-lin/FreePSXBoot", "Unirom — official project guide" to "https://unirom.github.io/", "XStation — releases and installation guides" to "https://github.com/x-station/xstation-releases") + consoleBasics),

        retroGuide("retro.ps2-homebrew", "PlayStation 2: homebrew and OPL", "A model-aware map of PS2 homebrew entry points and Open PS2 Loader. Installation routes differ by console revision and available accessories.",
            block("Useful projects", "Open PS2 Loader (OPL) is an open-source PS2 game and application loader. Use its project documentation for supported features and setup.", "Free McBoot and related boot methods depend on console compatibility and the installer used; check the current project instructions before preparing a memory card.", "The ps2homebrew GitHub organisation hosts free tools and projects for PS2 hardware."),
            block("Record and protect", "Record the SCPH model, region, any modchip, memory-card type and whether the console has a network adapter or internal drive.", "Back up memory-card saves before installing or reformatting boot media.", "Use homebrew and personally owned backups only; this guide does not link to commercial game files."),
            sources = listOf("PS2 Homebrew Projects — official project organisation" to "https://github.com/ps2homebrew", "Open PS2 Loader — source and releases" to "https://github.com/ps2homebrew/Open-PS2-Loader", "Free McBoot Installer — project repository" to "https://github.com/israpps/FreeMcBoot-Installer") + consoleBasics),

        retroGuide("retro.ps2-loading-options", "PS2 storage and Open PS2 Loader paths", "Compare the main OPL loading routes before preparing media. Console revision, network adapter, storage format, OPL version and game compatibility all matter.",
            block("Choose a path", "Internal HDD loading is available only on compatible Fat PS2 hardware with a suitable network adapter/interface and storage setup. Check the exact console and adapter before buying parts.", "SMB loading uses a computer or NAS share over Ethernet. Confirm the OPL version's network settings, account permissions and supported share configuration; keep the share on a trusted LAN.", "USB loading is convenient but uses the PS2's USB 1.1 ports, so throughput is limited. Fragmentation and image/layout requirements can affect compatibility.", "MX4SIO is a third-party SD-card interface, not an official Sony feature. It requires compatible hardware and OPL support; title compatibility is not universal."),
            block("Prepare and troubleshoot", "Back up memory-card saves and keep an untouched copy of any personally made disc image before conversion or renaming.", "Use the OPL documentation for the exact media format, file naming, partition or share setup required by your chosen release.", "If a title does not appear, first check the game ID/name, filesystem, share visibility and OPL version. If it appears but fails to load, compare with OPL's compatibility reports and test another known-good homebrew title.", "Do not treat a loading method or compatibility list as permission to download commercial game images."),
            sources = listOf("Open PS2 Loader — project and documentation" to "https://github.com/ps2homebrew/Open-PS2-Loader", "PS2 Homebrew Projects" to "https://github.com/ps2homebrew")),

        retroGuide("retro.ps3-homebrew", "PlayStation 3: HEN, CFW and homebrew", "PS3 modification depends on the exact CECH model and firmware. HEN and custom firmware are different routes; not every console supports CFW.",
            block("Identify the console", "Record the CECH model code, date code if available, current firmware, and the minimum firmware shown in System Information or a trusted model reference.", "The PS3HEN 3.6.0 project README, checked 19 October 2026, lists CEX OFW 4.80–4.82 and CEX HFW 4.83.1–4.93.1, plus DEX OFW 4.82 and DEX HFW 4.84.2. Confirm the exact firmware variant and current installer instructions before acting.", "Those PS3HEN entries describe HEN support only. They do not make a console CFW-compatible. For CFW eligibility, verify the exact model and minimum version using a maintained PS3-specific guide before changing firmware.", "Do not install a firmware package unless it matches the console model and the guide's stated route."),
            block("Homebrew and stores", "PS3HEN is an open-source Homebrew Enabler; follow its own release notes and supported firmware list.", "Browse homebrew tools from the project or developer pages. Treat third-party store packages cautiously and check who maintains them.", "Avoid stores or packages that offer copyrighted commercial games without authorisation."),
            sources = listOf("PS3Xploit — PS3HEN official source" to "https://github.com/PS3Xploit/PS3HEN", "PS3 Homebrew and CFW guide" to "https://www.psx-place.com/forums/ps3-guides.33/") + consoleBasics),

        retroGuide("retro.ps3-cfw-hen-check", "PS3 firmware check: CFW eligibility versus HEN", "Use separate checks for custom-firmware eligibility and HEN support. A firmware number by itself does not establish that a PS3 model can install CFW.",
            block("Record the console", "Write down the complete CECH model, current System Software version, date code if available, and whether it is retail CEX or a different hardware variant.", "CFW eligibility depends on hardware generation and the console's minimum supported firmware, not just the current installed version. Consult a maintained model-specific guide and confirm its evidence before changing anything.", "HEN is a separate route. PS3HEN 3.6.0's upstream README lists CEX OFW 4.80–4.82 and CEX HFW 4.83.1–4.93.1, plus DEX OFW 4.82 and DEX HFW 4.84.2. That list is not a CFW compatibility table."),
            block("Safe decision sequence", "Do not install a package until the exact model, firmware variant and required HFW/OFW starting point match the upstream instructions.", "Save the current system information and back up saves before any flash or storage operation.", "If the guide omits your exact model or firmware, stop and seek current specialist confirmation rather than extrapolating from a nearby CECH code.", "HEN and CFW differ in capabilities, installation route and runtime behavior; guides that use the terms interchangeably are unreliable."),
            sources = listOf("PS3HEN upstream README and supported firmware" to "https://github.com/PS3Xploit/PS3HEN", "PS3 model/firmware research community" to "https://www.psx-place.com/forums/ps3-guides.33/")),

        retroGuide("retro.ps4-homebrew", "PlayStation 4: firmware-aware homebrew", "PS4 homebrew availability is firmware-dependent and can change. Do not update the console until you have checked current compatibility for your exact system software.",
            block("Start with exact facts", "Record CUH model and full System Software version; include any previous modifications.", "Use the current PS4 CFW Guide compatibility page to understand supported routes and limitations.", "GoldHEN is a Homebrew Enabler project. Read its own release notes and compatibility information; do not assume every firmware or model is supported.", "Treat video tutorials as supplementary. Match the version and date of the video to the current project documentation."),
            block("Homebrew catalogues", "PKG-Zone operates a PlayStation homebrew catalogue and provides an install page. Review each listed app and its upstream project before installing.", "Prefer developer GitHub releases or project pages when available.", "Use stores for lawful homebrew and tools; do not download commercial games you do not own or content you are not authorised to use."),
            sources = listOf("PS4 CFW Guide — compatibility and method overview" to "https://github.com/cfw-guide/ps4.cfw.guide", "GoldHEN — official project and releases" to "https://github.com/GoldHEN/GoldHEN", "PKG-Zone — homebrew catalogue" to "https://pkg-zone.com/") + consoleBasics),

        retroGuide("retro.ps4-firmware-check", "PS4 firmware compatibility: record and verify", "A repeatable firmware-check workflow for PS4 research. This guide intentionally provides no static jailbreak matrix because exploit and payload support changes over time.",
